//
// Native side of the SecureVault Safari extension.
//
// Safari hands every browser.runtime.sendNativeMessage() of the extension to
// this handler. It passes the message unchanged to the running SecureVault
// program through a Unix socket in the App Group folder (the only place the
// sandboxed extension may reach) and returns the program's reply. The content
// is encrypted end to end by the extension and the program; this file only
// relays it, like native-host/securevault_host.py does for Firefox.
//
// Replaces the SafariWebExtensionHandler.swift generated by
// safari-web-extension-converter (see build_safari.sh).
//

import Foundation
import SafariServices
import os.log

private let maxFrame = 1024 * 1024
private let socketName = "bridge.sock"
// Info.plist of the extension: $(TeamIdentifierPrefix)securevault.bridge
private let appGroupKey = "SecureVaultAppGroup"

private enum BridgeError: Error {
    case unavailable
    case badReply
}

class SafariWebExtensionHandler: NSObject, NSExtensionRequestHandling {

    func beginRequest(with context: NSExtensionContext) {
        let request = context.inputItems.first as? NSExtensionItem
        let message: Any?
        if #available(macOS 14.0, *) {
            message = request?.userInfo?[SFExtensionMessageKey]
        } else {
            message = request?.userInfo?["message"]
        }

        DispatchQueue.global(qos: .userInitiated).async {
            let reply = self.relay(message)
            let response = NSExtensionItem()
            if #available(macOS 14.0, *) {
                response.userInfo = [SFExtensionMessageKey: reply]
            } else {
                response.userInfo = ["message": reply]
            }
            context.completeRequest(returningItems: [response], completionHandler: nil)
        }
    }

    private func relay(_ message: Any?) -> Any {
        guard let message = message, JSONSerialization.isValidJSONObject(message),
              let body = try? JSONSerialization.data(withJSONObject: message) else {
            return ["type": "error", "code": "bad_message"]
        }
        guard let path = socketPath() else {
            os_log(.error, "SecureVault: App Group is not configured")
            return ["type": "error", "code": "host_missing"]
        }
        do {
            let replyData = try exchange(body, socketPath: path)
            return try JSONSerialization.jsonObject(with: replyData)
        } catch {
            return ["type": "error", "code": "app_not_running"]
        }
    }

    private func socketPath() -> String? {
        guard let group = Bundle.main.object(forInfoDictionaryKey: appGroupKey) as? String, !group.isEmpty,
              let folder = FileManager.default.containerURL(forSecurityApplicationGroupIdentifier: group) else {
            return nil
        }
        return folder.appendingPathComponent(socketName).path
    }

    private func exchange(_ body: Data, socketPath: String) throws -> Data {
        let fd = socket(AF_UNIX, SOCK_STREAM, 0)
        guard fd >= 0 else { throw BridgeError.unavailable }
        defer { close(fd) }

        var one: Int32 = 1
        setsockopt(fd, SOL_SOCKET, SO_NOSIGPIPE, &one, socklen_t(MemoryLayout<Int32>.size))
        var timeout = timeval(tv_sec: 10, tv_usec: 0)
        setsockopt(fd, SOL_SOCKET, SO_RCVTIMEO, &timeout, socklen_t(MemoryLayout<timeval>.size))
        setsockopt(fd, SOL_SOCKET, SO_SNDTIMEO, &timeout, socklen_t(MemoryLayout<timeval>.size))

        var address = sockaddr_un()
        address.sun_family = sa_family_t(AF_UNIX)
        let pathBytes = Array(socketPath.utf8)
        guard pathBytes.count < MemoryLayout.size(ofValue: address.sun_path) else { throw BridgeError.unavailable }
        withUnsafeMutableBytes(of: &address.sun_path) { raw in
            raw.copyBytes(from: pathBytes)
        }
        let connected = withUnsafePointer(to: &address) { pointer in
            pointer.withMemoryRebound(to: sockaddr.self, capacity: 1) {
                connect(fd, $0, socklen_t(MemoryLayout<sockaddr_un>.size))
            }
        }
        guard connected == 0 else { throw BridgeError.unavailable }

        let length = UInt32(body.count)
        var frame = Data([UInt8(length & 0xff), UInt8((length >> 8) & 0xff),
                          UInt8((length >> 16) & 0xff), UInt8((length >> 24) & 0xff)])
        frame.append(body)
        try writeAll(fd, frame)

        let header = try readExact(fd, 4)
        let replyLength = Int(header[0]) | Int(header[1]) << 8 | Int(header[2]) << 16 | Int(header[3]) << 24
        guard replyLength <= maxFrame else { throw BridgeError.badReply }
        return try readExact(fd, replyLength)
    }

    private func writeAll(_ fd: Int32, _ data: Data) throws {
        var offset = 0
        while offset < data.count {
            let written = data.withUnsafeBytes { raw in
                write(fd, raw.baseAddress!.advanced(by: offset), data.count - offset)
            }
            guard written > 0 else { throw BridgeError.unavailable }
            offset += written
        }
    }

    private func readExact(_ fd: Int32, _ count: Int) throws -> [UInt8] {
        var buffer = [UInt8](repeating: 0, count: count)
        var offset = 0
        while offset < count {
            let got = buffer.withUnsafeMutableBytes { raw in
                read(fd, raw.baseAddress!.advanced(by: offset), count - offset)
            }
            guard got > 0 else { throw BridgeError.unavailable }
            offset += got
        }
        return buffer
    }
}
